#include <bits/stdc++.h>
using namespace std;
struct BIT {
    int n;
    vector<long long> f;
    BIT(int n) : n(n), f(n + 1) {
    }
    void add(int i, long long v) {
        for (; i <= n; i += i & -i)
            f[i] += v;
    }
    long long sum(int i) {
        long long s = 0;
        for (; i; i -= i & -i)
            s += f[i];
        return s;
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> q;
    struct Op {
        int t, k;
        string s;
    };
    vector<Op> ops;
    vector<string> a;
    while (q--) {
        int t, k = 0;
        string s;
        cin >> t >> s;
        if (t == 3)
            cin >> k;
        else
            a.push_back(s);
        ops.push_back({t, k, s});
    }
    sort(a.begin(), a.end());
    a.erase(unique(a.begin(), a.end()), a.end());
    BIT b(a.size());
    vector<int> cnt(a.size());
    for (auto o : ops) {
        int l = lower_bound(a.begin(), a.end(), o.s) - a.begin();
        if (o.t != 3) {
            int d = o.t == 1 ? 1 : (cnt[l] > 0 ? -1 : 0);
            cnt[l] += d;
            b.add(l + 1, d);
        } else {
            int r = lower_bound(a.begin(), a.end(), o.s + "{") - a.begin();
            if (b.sum(r) - b.sum(l) < o.k) {
                cout << "NONE\n";
                continue;
            }
            long long k = b.sum(l) + o.k;
            int pos = 0;
            for (int z = 1 << 18; z; z >>= 1)
                if (pos + z <= b.n && b.f[pos + z] < k) {
                    k -= b.f[pos + z];
                    pos += z;
                }
            cout << a[pos] << '\n';
        }
    }
}

#include <bits/stdc++.h>
using namespace std;
struct BIT {
    int n;
    vector<long long> f;
    BIT(int n) : n(n), f(n + 1) {
    }
    void add(int i, long long v) {
        for (; i <= n; i += i & -i)
            f[i] += v;
    }
    long long sum(int i) {
        long long s = 0;
        for (; i; i -= i & -i)
            s += f[i];
        return s;
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    vector<long long> x(n), c(n), vals;
    map<long long, vector<long long>> vs;
    for (int i = 0; i < n; i++) {
        cin >> x[i] >> c[i];
        vals.push_back(x[i]);
        vs[c[i]].push_back(x[i]);
    }
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    map<long long, BIT> bs;
    for (auto &[t, v] : vs) {
        sort(v.begin(), v.end());
        v.erase(unique(v.begin(), v.end()), v.end());
        bs.emplace(t, BIT(v.size()));
    }
    BIT all(vals.size());
    long long ans = 0;
    auto rank = [&](auto &v, long long y) {
        return int(lower_bound(v.begin(), v.end(), y) - v.begin()) + 1;
    };
    for (int i = 0; i < n; i++) {
        int r = rank(vals, x[i]), s = rank(vs[c[i]], x[i]);
        auto &b = bs.at(c[i]);
        ans += all.sum(all.n) - all.sum(r) - b.sum(b.n) + b.sum(s);
        all.add(r, 1);
        b.add(s, 1);
        if (i >= k) {
            int j = i - k, rj = rank(vals, x[j]), sj = rank(vs[c[j]], x[j]);
            auto &bj = bs.at(c[j]);
            all.add(rj, -1);
            bj.add(sj, -1);
            ans -= all.sum(rj - 1) - bj.sum(sj - 1);
        }
        if (i >= k - 1)
            cout << ans << (i == n - 1 ? '\n' : ' ');
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n), mn(4 * n), lazy(4 * n);
    for (auto &x : a)
        cin >> x;
    function<void(int, int, int)> build = [&](int p, int l, int r) {
        if (l == r) {
            mn[p] = a[l];
            return;
        }
        int m = (l + r) / 2;
        build(p * 2, l, m);
        build(p * 2 + 1, m + 1, r);
        mn[p] = min(mn[p * 2], mn[p * 2 + 1]);
    };
    auto push = [&](int p) {
        for (int z : {p * 2, p * 2 + 1}) {
            mn[z] += lazy[p];
            lazy[z] += lazy[p];
        }
        lazy[p] = 0;
    };
    function<void(int, int, int, int, int, long long)> upd =
        [&](int p, int l, int r, int L, int R, long long d) {
            if (r < L || R < l)
                return;
            if (L <= l && r <= R) {
                mn[p] += d;
                lazy[p] += d;
                return;
            }
            push(p);
            int m = (l + r) / 2;
            upd(p * 2, l, m, L, R, d);
            upd(p * 2 + 1, m + 1, r, L, R, d);
            mn[p] = min(mn[p * 2], mn[p * 2 + 1]);
        };
    function<int(int, int, int, int, int, long long)> find =
        [&](int p, int l, int r, int L, int R, long long h) {
            if (r < L || R < l || mn[p] > h)
                return -1;
            if (l == r)
                return l + 1;
            push(p);
            int m = (l + r) / 2, z = find(p * 2, l, m, L, R, h);
            return z != -1 ? z : find(p * 2 + 1, m + 1, r, L, R, h);
        };
    build(1, 0, n - 1);
    while (q--) {
        int t, l, r;
        long long d;
        cin >> t >> l >> r >> d;
        if (t == 1)
            upd(1, 0, n - 1, l - 1, r - 1, d);
        else
            cout << find(1, 0, n - 1, l - 1, r - 1, d) << '\n';
    }
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> a(n);
    for (auto &x : a)
        cin >> x;
    struct Node {
        int l = 0, r = 0;
        long long s = 0, m = 0;
    };
    vector<Node> tr(1);
    function<int(int, int)> build = [&](int l, int r) {
        int p = tr.size();
        tr.push_back({});
        if (l == r) {
            tr[p].s = tr[p].m = a[l];
            return p;
        }
        int m = (l + r) / 2;
        int x = build(l, m), y = build(m + 1, r);
        tr[p] = {x, y, tr[x].s + tr[y].s, min(tr[x].m, tr[y].m)};
        return p;
    };
    function<int(int, int, int, int, long long)> upd = [&](int old, int l, int r, int x,
                                                           long long d) {
        int p = tr.size();
        tr.push_back(tr[old]);
        if (l == r) {
            tr[p].s += d;
            tr[p].m += d;
            return p;
        }
        int m = (l + r) / 2;
        if (x <= m) {
            int z = upd(tr[p].l, l, m, x, d);
            tr[p].l = z;
        } else {
            int z = upd(tr[p].r, m + 1, r, x, d);
            tr[p].r = z;
        }
        tr[p].s = tr[tr[p].l].s + tr[tr[p].r].s;
        tr[p].m = min(tr[tr[p].l].m, tr[tr[p].r].m);
        return p;
    };
    function<pair<long long, long long>(int, int, int, int, int)> get =
        [&](int p, int l, int r, int L, int R) -> pair<long long, long long> {
        if (r < L || R < l)
            return {0, LLONG_MAX};
        if (L <= l && r <= R)
            return {tr[p].s, tr[p].m};
        int m = (l + r) / 2;
        auto x = get(tr[p].l, l, m, L, R), y = get(tr[p].r, m + 1, r, L, R);
        return {x.first + y.first, min(x.second, y.second)};
    };
    vector<int> root(q + 1);
    root[0] = build(0, n - 1);
    for (int i = 1; i <= q; i++) {
        int t, v, x;
        long long y;
        cin >> t >> v >> x >> y;
        if (t == 1)
            root[i] = upd(root[v], 0, n - 1, x - 1, y);
        else {
            root[i] = root[v];
            auto z = get(root[v], 0, n - 1, x - 1, y - 1);
            cout << z.first << ' ' << z.second << '\n';
        }
    }
}

