import sys
from array import array

v = list(map(int, sys.stdin.buffer.read().split()))
n, q = v[:2]
a = v[2 : 2 + n]
lc = array("i", [0])
rc = array("i", [0])
sm = array("q", [0])
mn = array("q", [0])


def node(l, r, s, m):
    p = len(sm)
    lc.append(l)
    rc.append(r)
    sm.append(s)
    mn.append(m)
    return p


def build(l, r):
    if l == r:
        return node(0, 0, a[l], a[l])
    m = (l + r) // 2
    x = build(l, m)
    y = build(m + 1, r)
    return node(x, y, sm[x] + sm[y], min(mn[x], mn[y]))


def upd(p, l, r, x, d):
    if l == r:
        return node(0, 0, sm[p] + d, mn[p] + d)
    m = (l + r) // 2
    u, w = lc[p], rc[p]
    if x <= m:
        u = upd(u, l, m, x, d)
    else:
        w = upd(w, m + 1, r, x, d)
    return node(u, w, sm[u] + sm[w], min(mn[u], mn[w]))


def get(p, l, r, L, R):
    if r < L or R < l:
        return (0, 10**30)
    if L <= l and r <= R:
        return sm[p], mn[p]
    m = (l + r) // 2
    x, y = get(lc[p], l, m, L, R), get(rc[p], m + 1, r, L, R)
    return x[0] + y[0], min(x[1], y[1])


root = [build(0, n - 1)]
out = []
for j in range(2 + n, len(v), 4):
    t, b, x, y = v[j : j + 4]
    if t == 1:
        root.append(upd(root[b], 0, n - 1, x - 1, y))
    else:
        root.append(root[b])
        s, m = get(root[b], 0, n - 1, x - 1, y - 1)
        out.append(f"{s} {m}")
print("\n".join(out))

