#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    using P = pair<long long, long long>;
    auto merge = [](P a, P b) {
        if (a.first == b.first)
            return P(a.first, a.second + b.second);
        if (a.second < b.second)
            swap(a, b);
        return P(a.first, a.second - b.second);
    };
    int z = 1;
    while (z < n)
        z *= 2;
    vector<P> tr(2 * z);
    vector<long long> pre(n + 1);
    map<long long, vector<int>> pos;
    map<long long, vector<long long>> sums;
    for (int i = 0; i < n; i++) {
        long long t, w;
        cin >> t >> w;
        tr[z + i] = {t, w};
        pre[i + 1] = pre[i] + w;
        pos[t].push_back(i);
        auto &s = sums[t];
        if (s.empty())
            s.push_back(0);
        s.push_back(s.back() + w);
    }
    for (int i = z - 1; i; i--)
        tr[i] = merge(tr[i * 2], tr[i * 2 + 1]);
    while (q--) {
        int l, r;
        long long p, d;
        cin >> l >> r >> p >> d;
        int L = l - 1 + z, R = r + z;
        P a = {0, 0}, b = {0, 0};
        while (L < R) {
            if (L & 1)
                a = merge(a, tr[L++]);
            if (R & 1)
                b = merge(tr[--R], b);
            L /= 2;
            R /= 2;
        }
        long long t = merge(a, b).first, w = 0;
        if (pos.count(t)) {
            auto &v = pos[t];
            auto &s = sums[t];
            w = s[lower_bound(v.begin(), v.end(), r) - v.begin()] -
                s[lower_bound(v.begin(), v.end(), l - 1) - v.begin()];
        }
        cout << ((__int128)w * d > (__int128)(pre[r] - pre[l - 1]) * p ? t : -1)
             << '\n';
    }
}

