    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> t(n), val(n);
    for (int i = 0; i < n; i++)
        cin >> t[i] >> val[i];
    vector<int> ord(n), pa(n), on(n), sz(n, 1);
    for (auto &x : ord) {
        cin >> x;
        --x;
    }
    iota(pa.begin(), pa.end(), 0);
    vector<unordered_map<long long, int>> cnt(n);
    vector<long long> ans(n + 1);
    function<int(int)> find = [&](int x) {
        return pa[x] == x ? x : pa[x] = find(pa[x]);
    };
    long long best = 0;
    auto unite = [&](int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return;
        if (sz[a] < sz[b])
            swap(a, b);
        sz[a] += sz[b];
        val[a] += val[b];
        for (auto [t, c] : cnt[b]) {
            val[a] += 1LL * c * cnt[a][t];
            cnt[a][t] += c;
        }
        cnt[b].clear();
        pa[b] = a;
        best = max(best, val[a]);
    };
    for (int i = n - 1; i >= 0; i--) {
        int x = ord[i];
        on[x] = 1;
        cnt[x][t[x]] = 1;
        best = max(best, val[x]);
        if (x && on[x - 1])
            unite(x, x - 1);
        if (x + 1 < n && on[x + 1])
            unite(x, x + 1);
        ans[i] = best;
    }
    while (q--) {
        int x;
        cin >> x;
        cout << ans[x] << '\n';
    }
}

