#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const long long M = 1000000007;
    auto pw = [&](long long a, long long b) {
        long long r = 1;
        for (; b; b >>= 1, a = a * a % M)
            if (b & 1)
                r = r * a % M;
        return r;
    };
    int n, m, K;
    cin >> n >> m >> K;
    vector<array<int, 3>> e(m);
    for (auto &v : e) {
        cin >> v[0] >> v[1] >> v[2];
        --v[0];
        --v[1];
    }
    vector<long long> ys(n);
    for (int x = 0; x < n; x++) {
        int d = n - 1;
        vector<vector<long long>> a(d, vector<long long>(d));
        for (auto [u, v, c] : e)
            if (u != v) {
                long long w = c ? x : 1;
                if (u < d)
                    a[u][u] = (a[u][u] + w) % M;
                if (v < d)
                    a[v][v] = (a[v][v] + w) % M;
                if (u < d && v < d) {
                    a[u][v] = (a[u][v] - w + M) % M;
                    a[v][u] = (a[v][u] - w + M) % M;
                }
            }
        long long det = 1;
        for (int i = 0; i < d; i++) {
            int p = i;
            while (p < d && !a[p][i])
                p++;
            if (p == d) {
                det = 0;
                break;
            }
            if (p != i) {
                swap(a[p], a[i]);
                det = (M - det) % M;
            }
            det = det * a[i][i] % M;
            long long inv = pw(a[i][i], M - 2);
            for (int j = i + 1; j < d; j++) {
                long long f = a[j][i] * inv % M;
                for (int k = i; k < d; k++)
                    a[j][k] = (a[j][k] - f * a[i][k] % M + M) % M;
            }
        }
        ys[x] = det;
    }
    long long ans = 0;
    for (int i = 0; i < n; i++) {
        vector<long long> p(1, 1);
        long long den = 1;
        for (int j = 0; j < n; j++)
            if (j != i) {
                vector<long long> v(p.size() + 1);
                for (int k = 0; k < (int)p.size(); k++) {
                    v[k] = (v[k] - j * p[k] % M + M) % M;
                    v[k + 1] = (v[k + 1] + p[k]) % M;
                }
                p.swap(v);
                den = den * (i - j + M) % M;
            }
        ans = (ans + ys[i] * p[K] % M * pw(den, M - 2)) % M;
    }
    cout << ans << '\n';
}

