#include <bits/stdc++.h>
using namespace std;
struct BIT {
    int n;
    vector<long long> f;
    BIT(int n) : n(n), f(n + 1) {
    }
    void add(int i, long long v) {
        for (; i <= n; i += i & -i)
            f[i] += v;
    }
    long long sum(int i) {
        long long s = 0;
        for (; i; i -= i & -i)
            s += f[i];
        return s;
    }
};
int main() {
