    cin.tie(nullptr);
    int R;
    cin >> R;
    vector<int> mu(R + 1), pr, lp(R + 1);
    mu[1] = 1;
    for (int i = 2; i <= R; i++) {
        if (!lp[i]) {
            lp[i] = i;
            pr.push_back(i);
            mu[i] = -1;
        }
        for (int p : pr) {
            if (1LL * i * p > R)
                break;
            lp[i * p] = p;
            if (i % p == 0) {
                mu[i * p] = 0;
                break;
            }
            mu[i * p] = -mu[i];
        }
    }
    auto isq = [](long long x) {
        long long r = sqrtl(x);
        while ((r + 1) * (r + 1) <= x)
            r++;
        while (r * r > x)
            r--;
        return r;
    };
    long long ans = 0, rr = 1LL * R * R;
    for (long long d = 1; d <= R; d += 2)
        if (mu[d]) {
            long long m = rr / (d * d), f = 0;
            for (long long x = 1; x * x < m; x++) {
                long long y = isq(m - x * x);
                f += (x % 2 ? y / 2 : (y + 1) / 2);
            }
            ans += mu[d] * f;
        }
    cout << ans << '\n';
}

