#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    struct Node {
        int n = 0, ones = 0, p[2][2] = {}, s[2][2] = {}, b[2][2] = {};
    };
    auto merge = [](Node a, Node b) {
        Node c;
        c.n = a.n + b.n;
        c.ones = a.ones + b.ones;
        for (int t = 0; t < 2; t++)
            for (int k = 0; k < 2; k++) {
                int ea = t ? a.n - a.ones : a.ones, eb = t ? b.n - b.ones : b.ones;
                c.p[t][k] = a.p[t][k];
                if (ea <= k)
                    c.p[t][k] = a.n + b.p[t][k - ea];
                c.s[t][k] = b.s[t][k];
                if (eb <= k)
                    c.s[t][k] = b.n + a.s[t][k - eb];
                c.b[t][k] = max(a.b[t][k], b.b[t][k]);
                for (int j = 0; j <= k; j++)
                    c.b[t][k] = max(c.b[t][k], a.s[t][j] + b.p[t][k - j]);
            }
        return c;
    };
    int n, q;
    string a;
    cin >> n >> q >> a;
    vector<Node> tr(4 * n);
    vector<int> lazy(4 * n);
    auto flip = [&](int p) {
        tr[p].ones = tr[p].n - tr[p].ones;
        for (int k = 0; k < 2; k++) {
            swap(tr[p].p[0][k], tr[p].p[1][k]);
            swap(tr[p].s[0][k], tr[p].s[1][k]);
            swap(tr[p].b[0][k], tr[p].b[1][k]);
        }
        lazy[p] ^= 1;
    };
    function<void(int, int, int)> build = [&](int p, int l, int r) {
        if (l == r) {
            tr[p].n = 1;
            tr[p].ones = a[l] - '0';
            for (int t = 0; t < 2; t++)
                for (int k = 0; k < 2; k++)
                    tr[p].p[t][k] = tr[p].s[t][k] = tr[p].b[t][k] =
                        (a[l] - '0' == t || k == 1);
            return;
        }
        int m = (l + r) / 2;
        build(p * 2, l, m);
        build(p * 2 + 1, m + 1, r);
        tr[p] = merge(tr[p * 2], tr[p * 2 + 1]);
    };
    auto push = [&](int p) {
        if (lazy[p]) {
            flip(p * 2);
            flip(p * 2 + 1);
            lazy[p] = 0;
        }
    };
    function<void(int, int, int, int, int)> upd = [&](int p, int l, int r, int L,
                                                      int R) {
        if (r < L || R < l)
            return;
        if (L <= l && r <= R) {
            flip(p);
            return;
        }
        push(p);
        int m = (l + r) / 2;
        upd(p * 2, l, m, L, R);
        upd(p * 2 + 1, m + 1, r, L, R);
        tr[p] = merge(tr[p * 2], tr[p * 2 + 1]);
    };
    function<Node(int, int, int, int, int)> get = [&](int p, int l, int r, int L,
                                                      int R) {
        if (r < L || R < l)
            return Node();
        if (L <= l && r <= R)
            return tr[p];
        push(p);
        int m = (l + r) / 2;
        return merge(get(p * 2, l, m, L, R), get(p * 2 + 1, m + 1, r, L, R));
    };
    build(1, 0, n - 1);
    while (q--) {
        int t, l, r;
        cin >> t >> l >> r;
        if (t == 1)
            upd(1, 0, n - 1, l - 1, r - 1);
        else
            cout << get(1, 0, n - 1, l - 1, r - 1).b[1][1] << '\n';
    }
}

