        ea = a[0] - a[1] if t else a[1]
        eb = b[0] - b[1] if t else b[1]
        for k in range(2):
            c[o + k] = a[o + k] if ea > k else a[0] + b[o + k - ea]
            c[o + 2 + k] = b[o + 2 + k] if eb > k else b[0] + a[o + 2 + k - eb]
            c[o + 4 + k] = max(
                a[o + 4 + k],
                b[o + 4 + k],
                *(a[o + 2 + j] + b[o + k - j] for j in range(k + 1)),
            )
    return tuple(c)


def flip(p):
    z = list(read(p))
    z[1] = z[0] - z[1]
    z[2:8], z[8:14] = z[8:14], z[2:8]
    put(p, z)
    lazy[p] ^= 1


def push(p):
    if lazy[p]:
        flip(2 * p)
        flip(2 * p + 1)
        lazy[p] = 0


def build(p, l, r):
    if l == r:
        b = int(a[l])
        put(
            p,
            (1, b)
            + tuple(x for t in range(2) for j in range(3) for x in (int(b == t), 1)),
        )
        return
    m = (l + r) // 2
    build(2 * p, l, m)
    build(2 * p + 1, m + 1, r)
    put(p, merge(read(2 * p), read(2 * p + 1)))


def upd(p, l, r, L, R):
    if r < L or R < l:
        return
    if L <= l and r <= R:
        flip(p)
        return
    push(p)
    m = (l + r) // 2
    upd(2 * p, l, m, L, R)
    upd(2 * p + 1, m + 1, r, L, R)
    put(p, merge(read(2 * p), read(2 * p + 1)))


def get(p, l, r, L, R):
    if r < L or R < l:
        return zero
    if L <= l and r <= R:
        return read(p)
    push(p)
    m = (l + r) // 2
    return merge(get(2 * p, l, m, L, R), get(2 * p + 1, m + 1, r, L, R))


