#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    using I = __int128_t;
    function<long long(long long, long long, long long &, long long &)> eg =
        [&](long long a, long long b, long long &x, long long &y) {
            if (!b) {
                x = 1;
                y = 0;
                return a;
            }
            long long u, v, g = eg(b, a % b, u, v);
            x = v;
            y = u - a / b * v;
            return g;
        };
    auto mod = [](I a, I m) { return (a % m + m) % m; };
    auto crt = [&](I a, I m, long long b, long long n) -> pair<I, I> {
        long long g = gcd((long long)(m % n), n);
        if ((b - a) % g)
            return {-1, 0};
        long long nn = n / g, x, y;
        eg((long long)((m / g) % nn), nn, x, y);
        I k = mod((b - a) / g * x, nn), l = m * nn;
        return {mod(a + m * k, l), l};
    };
    auto count = [](I a, I m, long long L, long long R) -> long long {
        if (a < 0 || a > R)
            return 0;
        I lo = L <= a ? 0 : (I(L) - a + m - 1) / m, hi = (I(R) - a) / m;
        return hi >= lo ? (long long)(hi - lo + 1) : 0;
    };
    int q;
    cin >> q;
    while (q--) {
        long long L, R, m, a, n, b, d;
        cin >> L >> R >> m >> a >> n >> b >> d;
        auto [r, p] = crt(a, m, b, n);
        if (r < 0) {
            cout << 0 << '\n';
            continue;
        }
        auto [s, z] = crt(r, p, 0, d);
        cout << count(r, p, L, R) - count(s, z, L, R) << '\n';
    }
}

