    struct Node {
        array<int, 26> to;
        int link = -1, len = 0, pos = 0;
        Node() {
            to.fill(-1);
        }
    };
    vector<Node> st(1);
    int last = 0;
    vector<int> run(n);
    for (int i = 0; i < n; i++) {
        run[i] = (i && s[i] != s[i - 1] ? run[i - 1] + 1 : 1);
        int c = s[i] - 'a', cur = st.size();
        st.push_back(Node());
        st[cur].len = st[last].len + 1;
        st[cur].pos = i;
        int p = last;
        while (p != -1 && st[p].to[c] == -1) {
            st[p].to[c] = cur;
            p = st[p].link;
        }
        if (p == -1)
            st[cur].link = 0;
        else {
            int q = st[p].to[c];
            if (st[p].len + 1 == st[q].len)
                st[cur].link = q;
            else {
                int clone = st.size();
                st.push_back(st[q]);
                st[clone].len = st[p].len + 1;
                while (p != -1 && st[p].to[c] == q) {
                    st[p].to[c] = clone;
                    p = st[p].link;
                }
                st[q].link = st[cur].link = clone;
            }
        }
        last = cur;
    }
    long long ans = 0;
    for (int i = 1; i < (int)st.size(); i++) {
        int lo = max(L, st[st[i].link].len + 1),
            hi = min({R, st[i].len, run[st[i].pos]});
        ans += max(0, hi - lo + 1);
    }
    cout << ans << '\n';
}

