            return 0LL;
        int z = (cap + 1) * (P + 1) * 2;
        vector<long long> dp(z);
        auto ix = [&](int h, int p, int o) { return (h * (P + 1) + p) * 2 + o; };
        dp[ix(0, 0, 0)] = 1;
        for (int t = 0; t < 2 * n; t++) {
            vector<long long> nd(z);
            for (int h = 0; h <= cap; h++)
                for (int p = 0; p <= P; p++)
                    for (int o = 0; o < 2; o++) {
                        long long w = dp[ix(h, p, o)];
                        if (!w)
                            continue;
                        if (h < cap && (t + h) / 2 < n)
                            nd[ix(h + 1, p, 1)] = (nd[ix(h + 1, p, 1)] + w) % M;
                        if (h > 0 && p + o <= P)
                            nd[ix(h - 1, p + o, 0)] = (nd[ix(h - 1, p + o, 0)] + w) % M;
                    }
            dp.swap(nd);
        }
        return dp[ix(0, P, 0)];
    };
    cout << (solve(H) - solve(H - 1) + M) % M << '\n';
