        int u, v;
        cin >> u >> v;
        --u;
        --v;
        g[u].push_back(v);
        rg[v].push_back(u);
        edges.push_back({u, v});
    }
    vector<int> seen(n), order;
    function<void(int)> dfs = [&](int u) {
        seen[u] = 1;
        for (int v : g[u])
            if (!seen[v])
                dfs(v);
        order.push_back(u);
    };
    for (int i = 0; i < n; i++)
        if (!seen[i])
            dfs(i);
    vector<int> id(n, -1);
    function<void(int, int)> mark = [&](int u, int c) {
        id[u] = c;
        for (int v : rg[u])
            if (id[v] < 0)
                mark(v, c);
    };
    int C = 0;
    reverse(order.begin(), order.end());
    for (int u : order)
        if (id[u] < 0)
            mark(u, C++);
    vector<int> ind(C);
    for (auto [u, v] : edges)
        if (id[u] != id[v])
            ind[id[v]] = 1;
    const long long INF = 1LL << 60;
    vector<vector<long long>> yes(C);
    vector<long long> no(C, INF), any(C, INF);
    for (int u = 0; u < n; u++) {
        any[id[u]] = min(any[id[u]], cost[u]);
        if (b[u])
            yes[id[u]].push_back(cost[u]);
        else
            no[id[u]] = min(no[id[u]], cost[u]);
    }
    vector<long long> dp(K + 1, INF);
    dp[0] = 0;
    for (int c = 0; c < C; c++) {
        sort(yes[c].begin(), yes[c].end());
        vector<pair<int, long long>> op;
        if (K == 0)
            op.push_back({0, ind[c] ? 0 : any[c]});
        else {
            op.push_back({0, ind[c] ? 0 : no[c]});
            long long s = 0;
            for (int j = 1; j <= min(K, (int)yes[c].size()); j++) {
                s += yes[c][j - 1];
                op.push_back({j, s});
            }
        }
        vector<long long> nd(K + 1, INF);
        for (int k = 0; k <= K; k++)
            if (dp[k] != INF)
                for (auto [j, s] : op)
                    if (s != INF)
                        nd[min(K, k + j)] = min(nd[min(K, k + j)], dp[k] + s);
        dp.swap(nd);
    }
    cout << (dp[K] == INF ? -1 : dp[K]) << '\n';
}

