    map<array<int, 6>, int> memo;
    function<int(int, int, int, int, int, int)> f = [&](int a, int b, int c, int last,
                                                        int run, int k) {
        if (k < 0)
            return 0;
        if (a + b + c == 0)
            return int(k == 0);
        array<int, 6> key = {a, b, c, last, run, k};
        if (memo.count(key))
            return memo[key];
        int rem[3] = {a, b, c};
        long long ans = 0;
        for (int t = 0; t < 3; t++)
            if (rem[t] && !(t == last && run == 2)) {
                rem[t]--;
                ans += f(rem[0], rem[1], rem[2], t, t == last ? run + 1 : 1,
                         k - (last != 3 && last != t));
                rem[t]++;
            }
        return memo[key] = ans % M;
    };
    cout << f(A, B, C, 3, 0, K) << '\n';
}

