#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, q, A, B;
    cin >> n >> m >> q >> A >> B;
    vector<int> p(n), sz(n, 1), c0(n), c1(n);
    iota(p.begin(), p.end(), 0);
    for (int i = 0, c; i < n; i++) {
        cin >> c;
        c0[i] = c == 0;
        c1[i] = c == 1;
    }
    vector<pair<int, int>> e(m);
    for (auto &[u, v] : e) {
        cin >> u >> v;
        --u;
        --v;
    }
    vector<int> del(q), removed(m);
    for (auto &x : del) {
        cin >> x;
        removed[--x] = 1;
    }
    function<int(int)> find = [&](int x) { return p[x] == x ? x : p[x] = find(p[x]); };
    auto good = [&](int x) { return c0[x] >= A && c1[x] >= B; };
    int count = 0;
    for (int i = 0; i < n; i++)
        count += good(i);
    auto unite = [&](int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return;
        if (sz[a] < sz[b])
            swap(a, b);
        count -= good(a) + good(b);
        p[b] = a;
        sz[a] += sz[b];
        c0[a] += c0[b];
        c1[a] += c1[b];
        count += good(a);
    };
    for (int i = 0; i < m; i++)
        if (!removed[i])
            unite(e[i].first, e[i].second);
    vector<int> ans(q);
    for (int i = q - 1; i >= 0; i--) {
        ans[i] = count;
        auto [u, v] = e[del[i]];
        unite(u, v);
    }
    for (int x : ans)
        cout << x << '\n';
}

