        g[u - 1].push_back({v - 1, w, c});
    }
    const long long INF = 1LL << 60;
    vector<long long> d(n * 6, INF);
    using P = pair<long long, int>;
    priority_queue<P, vector<P>, greater<P>> q;
    d[4] = 0;
    q.push({0, 4});
    while (!q.empty()) {
        auto [du, s] = q.top();
        q.pop();
        if (du != d[s])
            continue;
        int u = s / 6, last = (s % 6) / 2, used = s % 2;
        for (auto [v, w, c] : g[u]) {
            int nu = used + (last == c);
            if (nu > 1)
                continue;
            int z = v * 6 + c * 2 + nu;
            if (du + w < d[z]) {
                d[z] = du + w;
                q.push({d[z], z});
            }
        }
    }
    long long ans = *min_element(d.begin() + 6 * (n - 1), d.end());
    cout << (ans == INF ? -1 : ans) << '\n';
}

