#include <bits/stdc++.h>
using namespace std;
struct BIT {
    int n;
    vector<long long> f;
    BIT(int n) : n(n), f(n + 1) {
    }
    void add(int i, long long v) {
        for (; i <= n; i += i & -i)
            f[i] += v;
    }
    long long sum(int i) {
        long long s = 0;
        for (; i; i -= i & -i)
            s += f[i];
        return s;
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long D, B;
    cin >> n >> D >> B;
    vector<pair<long long, long long>> a(n);
    vector<long long> p;
    for (auto &[x, y] : a) {
        cin >> x >> y;
        p.push_back(y);
    }
    sort(a.begin(), a.end());
    sort(p.begin(), p.end());
    p.erase(unique(p.begin(), p.end()), p.end());
    BIT bit(p.size());
    int l = 0;
    long long ans = 0;
    for (int r = 0; r < n; r++) {
        while (a[r].first - a[l].first > D) {
            bit.add(lower_bound(p.begin(), p.end(), a[l].second) - p.begin() + 1, -1);
            l++;
        }
        ans += bit.sum(upper_bound(p.begin(), p.end(), B - a[r].second) - p.begin());
        bit.add(lower_bound(p.begin(), p.end(), a[r].second) - p.begin() + 1, 1);
    }
    cout << ans << '\n';
}

