#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<array<long long, 3>> ev;
    vector<long long> ys;
    for (int i = 0; i < n; i++) {
        long long x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        ev.push_back({x1, y1, y2});
        ev.push_back({x2, y1, y2});
        ys.push_back(y1);
        ys.push_back(y2);
    }
    sort(ev.begin(), ev.end());
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    int N = ys.size() - 1;
    vector<long long> len(4 * N);
    vector<int> lazy(4 * N);
    auto flip = [&](int p, int l, int r) {
        len[p] = ys[r + 1] - ys[l] - len[p];
        lazy[p] ^= 1;
    };
    function<void(int, int, int, int, int)> upd = [&](int p, int l, int r, int L,
                                                      int R) {
        if (r < L || R < l)
            return;
        if (L <= l && r <= R) {
            flip(p, l, r);
            return;
        }
        int m = (l + r) / 2;
        if (lazy[p]) {
            flip(p * 2, l, m);
            flip(p * 2 + 1, m + 1, r);
            lazy[p] = 0;
        }
        upd(p * 2, l, m, L, R);
        upd(p * 2 + 1, m + 1, r, L, R);
        len[p] = len[p * 2] + len[p * 2 + 1];
    };
    long long ans = 0, last = ev[0][0];
    for (auto [x, l, r] : ev) {
        ans += (x - last) * len[1];
        last = x;
        int L = lower_bound(ys.begin(), ys.end(), l) - ys.begin(),
            R = lower_bound(ys.begin(), ys.end(), r) - ys.begin() - 1;
        upd(1, 0, N - 1, L, R);
    }
    cout << ans << '\n';
}

