#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    const int V = 1000000;
    vector<bool> ok(V + 1, true);
    vector<int> pr;
    for (int i = 2; i <= V; i++)
        if (ok[i]) {
            pr.push_back(i);
            if (1LL * i * i <= V)
                for (int j = i * i; j <= V; j += i)
                    ok[j] = false;
        }
    int q;
    cin >> q;
    while (q--) {
        long long g, l, T;
        cin >> g >> l >> T;
        if (l % g) {
            cout << 0 << '\n';
            continue;
        }
        long long c = l / g, x = c;
        vector<long long> powers;
        for (long long p : pr) {
            if (p * p > x)
                break;
            if (x % p == 0) {
                long long z = 1;
                while (x % p == 0) {
                    x /= p;
                    z *= p;
                }
                powers.push_back(z);
            }
        }
        if (x > 1)
            powers.push_back(x);
        vector<long long> div = {1};
        for (auto p : powers) {
            int n = div.size();
            for (int i = 0; i < n; i++)
                div.push_back(div[i] * p);
        }
        int ans = 0;
        for (auto a : div)
            ans += g * (a + c / a) <= T;
        cout << ans << '\n';
    }
}

