v = list(map(int, sys.stdin.buffer.read().split()))
qs = [v[i : i + 3] for i in range(1, len(v), 3)]
V = isqrt(max((l // g for g, l, T in qs if l % g == 0), default=1))
ok = bytearray(b"\x01") * (V + 1)
pr = []
for i in range(2, V + 1):
    if ok[i]:
        pr.append(i)
        if i * i <= V:
            ok[i * i : V + 1 : i] = b"\x00" * ((V - i * i) // i + 1)
out = []
for g, l, T in qs:
    if l % g:
        out.append("0")
        continue
    c = x = l // g
    powers = []
    for p in pr:
        if p * p > x:
            break
        if x % p == 0:
            z = 1
            while x % p == 0:
                x //= p
                z *= p
            powers.append(z)
    if x > 1:
        powers.append(x)
    div = [1]
    for p in powers:
        div += [a * p for a in div]
    out.append(str(sum(g * (a + c // a) <= T for a in div)))
print("\n".join(out))

