#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, K;
    cin >> N >> K;
    vector<int> spf(N + 1);
    iota(spf.begin(), spf.end(), 0);
    for (int p = 2; p * p <= N; p++)
        if (spf[p] == p)
            for (int x = p * p; x <= N; x += p)
                if (spf[x] == x)
                    spf[x] = p;
    vector<unsigned char> cnt(N + 1), par(N + 1), bad(N + 1);
    int ans = K == 0;
    for (int x = 2; x <= N; x++) {
        int p = spf[x], m = x / p;
        if (m % p) {
            cnt[x] = cnt[m] + 1;
            par[x] = 1;
            bad[x] = bad[m];
        } else {
            cnt[x] = cnt[m];
            par[x] = par[m] ^ 1;
            bad[x] = bad[m] + (par[m] ? 1 : -1);
        }
        if (cnt[x] == K && !bad[x])
            ans++;
    }
    cout << ans << '\n';
}
